    while (true) {
        *ledA = 1;
        ThisThread::sleep_for(500ms);
        *ledA = 0;
        ThisThread::sleep_for(1500ms);
        printf("My LED is %s\n", *ledA ? "ON" : "OFF"); // Corrected printing
    }
}
