float raycast(vec2 origin, vec2 dir) {
    // Simplified raycasting implementation
    vec2 mapCoords = origin;
    float dist = 0.0;

    while (dist < 100.0) {
        vec2 texCoords = mod(mapCoords, 1.0);

        // Sample the map texture to check for walls
        float wall = texture(map, texCoords).r;

        if (wall > 0.5) {
            return dist;
        }

        dist += 0.1;
        mapCoords += dir;
    }

    return 100.0; // No wall hit
}

void main() {
    // Calculate ray direction based on screen coordinates and FOV
    vec2 dir = vec2(
        (gl_FragCoord.x / resolution.x - 0.5) * fov,
        (gl_FragCoord.y / resolution.y - 0.5) * fov
    );

    // Perform raycasting
    float distance = raycast(playerPos, dir);

    // Calculate color based on distance
    float brightness = 1.0 / (distance * 0.1);
    FragColor = vec4(brightness, brightness, brightness, 1.0);
}
