// Channel to queue jobs
$jobQueue = new Channel(1024);

// Worker function to process jobs
function worker() {
    global $semaphore, $jobQueue;

    while (true) {
        // Acquire a semaphore permit, blocking if none available
        $semaphore->acquire();

        // Get a job from the queue
        $job = $jobQueue->pop();

        if ($job) {
            // Process the job
            echo "Processing job: " . $job . PHP_EOL;
            // Simulate some work
            Coroutine::sleep(1);

            // Release the semaphore after processing
            $semaphore->release();
        }
    }
}

// Start multiple worker coroutines
for ($i = 0; $i < 5; $i++) {
    Coroutine::create('worker');
}

// Add jobs to the queue
