function findEntityValue(jsonData, entityKey) {
  const results = [];

  function search(obj, path = []) {
    for (const key in obj) {
      const newPath = [...path, key];

      if (key === entityKey) {
        results.push({ key: entityKey, value: obj[key], path: newPath });
      } else if (typeof obj[key] === 'object' && obj[key] !== null) {
        search(obj[key], newPath);
      }
    }
  }

  search(jsonData);

  return results;
}

