      requestFunction()
        .then(resolve)
        .catch(error => {
          attempts--;
          if (attempts > 0) {
            // Retry after a short delay (adjust as needed)
            setTimeout(attemptRequest, 1000);
          } else {
            reject(error);
          }
        });
    }

    attemptRequest();
  });
}

