        private void DrawSierpinskiTriangle(Canvas canvas, double x1, double y1, double size, int recursionLevel)
        {
            // Base case: draw a simple triangle
            if (recursionLevel == 0)
            {
                var triangle = new Polygon();
                triangle.Points.Add(new Point(x1, y1));
                triangle.Points.Add(new Point(x1 + size, y1));
                triangle.Points.Add(new Point(x1 + size / 2, y1 + size * Math.Sqrt(3) / 2));
                triangle.Fill = Brushes.Black;
                canvas.Children.Add(triangle);
            }
            else
