using System;
using System.Collections.Generic;
using System.Text.RegularExpressions;

public class HashtagExtractor
{
    public static List<string> ExtractHashtags(string text)
    {
        // This regex matches strings starting with '#' followed by one or more alphanumeric characters or underscores.
        Regex hashtagRegex = new Regex(@"#[\w]+", RegexOptions.IgnoreCase);

        // Find all matches in the text
        MatchCollection matches = hashtagRegex.Matches(text);

        // Extract the matched hashtags into a list
        List<string> hashtags = new List<string>();
        foreach (Match match in matches)
        {
            hashtags.Add(match.Value);
        }

        return hashtags;
    }
}

public class Example
{
    public static void Main(string[] args)
    {
        string text = "This is a tweet with #hashtags #and #multiple #hashtags.";

        List<string> hashtags = HashtagExtractor.ExtractHashtags(text);

        Console.WriteLine("Hashtags found:");
        foreach (string hashtag in hashtags)
        {
            Console.WriteLine(hashtag);
        }
    }
}
```

